import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid invoice with one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].unitPrice, 8500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice creates a valid invoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-06-20',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 20 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[2].name, 'Logo package');
});

test('createInvoice rejects an unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects an invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '01/15/2024',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects a malformed date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects a non-string date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: 20240115,
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a non-array lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: null,
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a non-integer quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5.5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects an unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice rejects the first invalid line in a multi-line request', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 0 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice handles products with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  };
  const originalLine = { ...input.lines[0] };
  createInvoice(input);
  assert.deepEqual(input.lines[0], originalLine);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 10, unitPrice: 8500 };
  assert.equal(lineTotal(line), 85000);
});

test('lineTotal works with single quantity', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 1000, unitPrice: 50 };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals with a single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 85000, discount: 0, total: 85000 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 20, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 5 * 8500 + 20 * 9500 + 1 * 120000;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000 }],
  };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals works with an invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 5 * 8500 + 10 * 9500;
  const discount = subtotal * 5 / 100;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, Math.round(discount));
  assert.equal(totals.total, subtotal - Math.round(discount));
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[0].sku, 'DES-HOUR');
  assert.equal(addResult.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(addResult.value.lines[1].qty, 10);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DES-HOUR', qty: 10 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 15);
});

test('addLine enriches new lines with product data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(addResult.ok, true);
  const newLine = addResult.value.lines[1];
  assert.equal(newLine.name, 'Logo package');
  assert.equal(newLine.unitPrice, 120000);
  assert.equal(newLine.vatRate, 21);
});

test('addLine rejects invalid quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 5.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects draft status requirement', () => {
  const nonDraftInvoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const originalLength = result.value.lines.length;
  addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(result.value.lines.length, originalLength);
});

test('removeLine removes a line from an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const removeResult = removeLine(result.value, 'DES-HOUR');
  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 1);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine returns LINE_NOT_FOUND for unknown SKU', () => {
  const result = createInvoice({
