import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText shows DRAFT for an invoice without a number', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
