    status: 'draft',
    lines: [
      { sku: 'SKU1', name: 'Product 1', qty: 1, unitPrice: 1000, vatRate: 21 },
      { sku: 'SKU2', name: 'Product 2', qty: 2, unitPrice: 2000, vatRate: 21 },
      { sku: 'SKU3', name: 'Product 3', qty: 3, unitPrice: 3000, vatRate: 21 },
    ],
  };
  const customer = { id: 'C-001', name: 'Test Customer' };
  const text = renderInvoiceText(invoice, customer);
  const textLines = text.split('\n');
  // DRAFT + Customer + 3 product lines + Subtotal + VAT + Total = 8 lines
  assert.equal(textLines.length, 8);
});

test('renderInvoiceText pads quantity with spaces', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'SKU1', name: 'Item 1', qty: 1, unitPrice: 1000, vatRate: 21 },
      { sku: 'SKU2', name: 'Item 2', qty: 100, unitPrice: 1000, vatRate: 21 },
      { sku: 'SKU3', name: 'Item 3', qty: 1000, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const customer = { id: 'C-001', name: 'Test' };
  const text = renderInvoiceText(invoice, customer);
  const lines = text.split('\n');
  // Check that quantities are aligned (padded to 3 chars)
  assert.match(lines[2], /^\s*1x/);
  assert.match(lines[3], /^\s*100x/);
  assert.match(lines[4], /^\s*1000x/);
});

test('renderInvoiceText handles single product invoice', () => {
  const invoice = {
    number: 'INV-2024-0042',
    customerId: 'C-003',
    issueDate: '2024-06-20',
    status: 'issued',
    lines: [
      { sku: 'BRAND-BOOK', name: 'Brand guidelines document', qty: 1, unitPrice: 245000, vatRate: 21 },
    ],
  };
  const customer = { id: 'C-003', name: 'Kite & Co' };
  const text = renderInvoiceText(invoice, customer);
  assert.ok(text.includes('INV-2024-0042'));
  assert.ok(text.includes('Kite & Co'));
  assert.ok(text.includes('Brand guidelines document'));
  assert.ok(text.includes('€2,450.00'));
  // With 21% VAT: 2450 * 0.21 = 514.50 -> 51450 cents
  // Total = 2450 + 514.50 = 2964.50 = 296450 cents
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText preserves customer object', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
    ],
  };
  const customer = { id: 'C-001', name: 'Test', email: 'test@example.com', country: 'NL' };
  const text = renderInvoiceText(invoice, customer);
  assert.ok(text.includes('Test'));
  // Verify customer object wasn't mutated
  assert.equal(customer.id, 'C-001');
  assert.equal(customer.email, 'test@example.com');
});

test('renderInvoiceText shows line discount if present', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };
  const customer = { id: 'C-001', name: 'Test' };
  const text = renderInvoiceText(invoice, customer);
  // Should show line total, discount, and final amount
  assert.ok(text.includes('€850.00')); // line total
  assert.ok(text.includes('€85.00')); // discount (10% of 850)
  assert.ok(text.includes('€765.00')); // final amount after discount
});

test('renderInvoiceText shows subtotal and discount lines when there is a discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };
  const customer = { id: 'C-001', name: 'Test' };
  const text = renderInvoiceText(invoice, customer);
  assert.ok(text.includes('Subtotal: €850.00'));
  assert.ok(text.includes('Discount: -€85.00'));
  // After discount: 850 - 85 = 765
  // VAT on 765: 765 * 21 / 100 = 160.65 -> 161 cents
  // Total: 765 + 161 = 926
  assert.ok(text.includes('Total:'));
  assert.ok(text.includes('VAT:'));
});

test('renderInvoiceText shows subtotal and VAT when VAT is present', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const customer = { id: 'C-001', name: 'Test' };
  const text = renderInvoiceText(invoice, customer);
  // Now shows subtotal and VAT because VAT > 0
  assert.ok(text.includes('Subtotal: €850.00'));
  assert.ok(!text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText handles mixed discount and no-discount lines', () => {
  const invoice = {
