    ],
  };
  const customer = { id: 'C-001', name: 'Test' };
  const text = renderInvoiceText(invoice, customer);
  // First line should show discount
  const lines = text.split('\n');
  assert.ok(lines[2].includes('-')); // line with discount has minus sign
  assert.ok(!lines[3].includes('-') || lines[3].includes('Discount: -')); // second line may not have discount, or it's the discount line
});

test('renderInvoiceText with decimal discount percentage', () => {
